import sympy
from sympy.combinatorics import SymmetricGroup, AlternatingGroup, DihedralGroup, CyclicGroup
from sympy.matrices import eye, zeros

# Top-level setup
S3 = SymmetricGroup(3)
S4 = SymmetricGroup(4)
A4 = AlternatingGroup(4)
D4 = DihedralGroup(4)
C4 = CyclicGroup(4)
V4 = AlternatingGroup(4)
Z2 = CyclicGroup(2)
Z3 = CyclicGroup(3)
Z4 = CyclicGroup(4)
Z6 = CyclicGroup(6)
trivial = CyclicGroup(1)
I2 = eye(2)
I3 = eye(3)
O2 = zeros(2,2)
O3 = zeros(3,3)

CONDITION_LABELS = [
    "H_1: R is a commutative ring with identity",
    "H_2: c(f) denotes the ideal generated by the coefficients of f",
    "¬Q: The equivalence between f being nilpotent and c(f) being in the nilradical fails"
]

N_HYP = 2
NEG_Q_INDEX = 2

class RingWrapper:
    def __init__(self, witness):
        if isinstance(witness, dict):
            self.ring_elements = witness['elements']
            self.zero = witness['zero']
            self.one = witness['one']
            self.add = witness['add']
            self.mul = witness['mul']
            self.f = witness['f']
        elif hasattr(witness, 'ring_elements') and hasattr(witness, 'f'):
            self.ring_elements = witness.ring_elements
            self.zero = witness.zero
            self.one = witness.one
            self.add = witness.add
            self.mul = witness.mul
            self.f = witness.f
        elif isinstance(witness, tuple) and len(witness) == 2 and isinstance(witness[0], int):
            n, coeffs = witness
            self.n = n
            self.ring_elements = list(range(n))
            self.zero = 0
            self.one = 1 % n
            self.f = [c % n for c in coeffs]
            self.add = lambda a, b: (a + b) % n
            self.mul = lambda a, b: (a * b) % n
        else:
            raise ValueError("Unknown witness format")

def conditions(witness):
    # Handle sympy Poly fallback
    is_sympy = False
    if hasattr(witness, 'is_Poly'):
        f_poly = witness
        R_domain = f_poly.domain
        is_sympy = True
    elif isinstance(witness, tuple) and len(witness) == 2 and hasattr(witness[1], 'is_Poly'):
        R_domain, f_poly = witness
        is_sympy = True
        
    if is_sympy:
        try:
            h1 = bool(R_domain.is_commutative)
            h2 = True
            cf_in_nil = all(c.is_nilpotent for c in f_poly.coeffs())
            f_is_nil = cf_in_nil
            q = (f_is_nil == cf_in_nil)
            neg_q = not q
            return [h1, h2, neg_q]
        except Exception:
            return [False, False, False]

    try:
        rw = RingWrapper(witness)
    except Exception:
        return [False, False, False]

    # H1: R is a commutative ring with identity
    try:
        is_comm = True
        for a in rw.ring_elements:
            for b in rw.ring_elements:
                if rw.mul(a, b) != rw.mul(b, a):
                    is_comm = False
                    break
            if not is_comm:
                break
        
        is_id = True
        for a in rw.ring_elements:
            if rw.mul(a, rw.one) != a or rw.mul(rw.one, a) != a:
                is_id = False
                break
        
        h1 = is_comm and is_id
    except Exception:
        h1 = False

    # H2: c(f) denotes the ideal generated by the coefficients of f
    h2 = True

    # neg_Q: f is nilpotent in R[x] iff c(f) is contained in the nilradical of R
    try:
        cf_in_nil = True
        for c in rw.f:
            is_nil = False
            curr = c
            for _ in range(len(rw.ring_elements)):
                if curr == rw.zero:
                    is_nil = True
                    break
                curr = rw.mul(curr, c)
            if not is_nil:
                cf_in_nil = False
                break
        
        def poly_mul(p1, p2):
            if not p1 or not p2:
                return []
            deg1 = len(p1) - 1
            deg2 = len(p2) - 1
            res = [rw.zero] * (deg1 + deg2 + 1)
            for i in range(deg1 + 1):
                for j in range(deg2 + 1):
                    term = rw.mul(p1[i], p2[j])
                    res[i+j] = rw.add(res[i+j], term)
            while res and res[-1] == rw.zero:
                res.pop()
            return res

        f = list(rw.f)
        while f and f[-1] == rw.zero:
            f.pop()
        
        f_is_nil = False
        if not f:
            f_is_nil = True
        else:
            curr_f = f
            max_k = len(f) * len(rw.ring_elements)
            for _ in range(max_k):
                if not curr_f:
                    f_is_nil = True
                    break
                curr_f = poly_mul(curr_f, f)
            if not curr_f:
                f_is_nil = True
                
        q = (f_is_nil == cf_in_nil)
        neg_q = not q
    except Exception:
        neg_q = False

    return [h1, h2, neg_q]